-- 2026-11-13 全节重整 A2-2.5.1 ~ A2-2.5.5（方案 C，含重裁配图 p46_r0/p46_r1 及方法发展表/瀑布敏捷卡归入 2.5.1）
begin;

insert into kb_asset (sha256, path, w, h, kind, license)
values
  ('5b2643031848cb4d8c88ea952a06809a567f78f08336ad3a31a231ca83550985', '/kb-assets/theory/p46_r0_5b2643031848cb4d.png', 2000, 1138, 'figure', 'reference-digest'),
  ('679bfc278d4ceba438e81e3cec164c7194b7093365307f2e2a6a3fe0a406e104', '/kb-assets/theory/p46_r1_679bfc278d4ceba4.png', 1546, 768, 'figure', 'reference-digest')
