do $$
declare
  old_rev record;
  v_rev integer;
  v_blocks jsonb := $b87$[{"t": "list", "id": "a2-2-5-1-b1", "imp": "core", "title": "", "ordered": false, "items": ["1、^^软件危机^^：^^软件危机泛指在计算机软件的开发和维护过程中遇到的一系列严重的问题，集中表现在成本，质量，生产效率等几个方面。^^", "2、软件工程", "==（1）软件工程是指采用工程的概念、原理、技术和方法指导软件的开发与维护。==", "==（2）软件工程的主要思想强调在软件开发过程中需要应用工程化原则。==", "==（3）软件工程的核心思想是把软件当作一个工程产品来处理。==", "3、==软件工程三要素：方法、工具、过程。==", "@@记忆口诀@@： 阮三要（==软件工程三大要素==）一要芳芳（==方法==）为爱情，二要工作（==工具==）为事业，三要过日子（==过程==）为生活。", "==（1）方法：方法是完成软件工程项目的技术手段；为软件开发提供“如何做”的技术。==", "==（2）工具：工具支持软件的开发、管理、文档生成；提供的自动的或半自动的软件工程的支撑环境。==", "==（3）过程：过程支持软件开发的各个环节的控制、管理；获得高质量的软件所需要完成的一系列任务的框架。==", "==4、软件工程的目标（七大目标）：==", "@@记忆口诀：@@阮七目（==可移植性==）靠（==可靠性==）维（==可维护性==）修（==可修改性==）重（==可重用==）新追（==可追踪性==）你（==可理解性==）", "（1）==可修改性==：允许对系统进行修改而不增加原系统的复杂性。它支持软件的调试和维护，是一个难以达到的目标。", "（2）==可靠性==：能防止因概念、设计和结构等方面的不完善造成的软件系统失效，具有挽回因操作不当造成软件系统失效的能力。", "（3）==可理解性==：系统具有清晰的结构，能直接反映问题的需求。可理解性有助于控制系统软件复杂性，并支持软件的维护、移植或重用。", "（4）==可维护性==：软件交付使用后，能够对它进行修改，以改正潜伏的错误，改进性能和其它属性，使软件产品适应环境的变化等。软件维护费用在软件开发费用中占有很大的比重。可维护性是软件工程中一项十分重要的目标。", "（5）==可重用性==：把概念或功能相对独立的一个或一组相关模块定义为一个软部件。可组装在系统的任何位置，降低工作量。", "（6）==可移植性==：软件从一个计算机系统或环境搬到另一个计算机系统或环境的难易程度。", "（7）==可追踪性==：根据软件需求对软件设计、程序进行正向追踪，或根据软件设计、程序对软件需求的逆向追踪的能力。", "5、==软件工程原则（八大原则）：==", "@@记忆口诀@@： 阮八原（==软件工程八大原则==）居（==局部化==）然相信（==信息隐藏==）一（==一致性==）碗（==完备性==）", "馍（==模块化==）会因为缺（==确定性==）一克盐（==可验证性==）变臭（==抽象==）了。", "（1）==抽象==：采用分层次抽象，自顶向下、逐层细化的办法控制软件开发过程的复杂性。", "（2）==模块化==：模块化有助于信息隐蔽和抽象，有助于表示复杂的系统。", "模块化的独立性：==耦合度和内聚度是衡量软件模块独立性的主要标准==，软件设计应尽量做到==高内聚，低耦合==（==高内聚低耦合是判断软件设计好坏的标准==）。", "①、==内聚==：模块内部的紧密程度，模块内部联系越紧，模块与模块之间的耦合就会越低。", "②、==耦合==：模块与模块之间的联系或关联程度。", "（3）==信息隐蔽==：将模块设计成\"黑箱\"，实现的细节隐藏在模块内部，不让模块的使用者直接访问，这就是信息封装。", "（4）==局部化==：保证模块之间具有松散的耦合，模块内部具有较强的内聚，这有助于控制解的复杂性。", "（5）==确定性==：软件开发过程中所有概念的表达应是确定的、无歧义性的、规范的。", "（6）==一致性==：整个软件系统使用一致的概念、符号和术语。", "（7）==完备性==：软件系统不丢失任何重要成分，可以完全实现系统所要求功能的程度。", "（8）==可验证性==：易于检查、测试、评审，确保系统的正确性。", "6、软件工程过程", "（1）软件工程过程是把软件转化为输出的一组彼此相关的资源活动", "（2）软件工程过程的四个基本活动：", "@@记忆口诀@@： 阮四基（==软件工程的过程中四个基本活动==）", "一基小猪佩奇计划找1P（==Plan，软件规格说明==）,一起看2D(==Do，软件开发==)动画,发现没有安全的3C(==Check，软件确认==)电子产品，最后决定去4A(==Action，软件演进==)级景区玩，忽然两人互相看看了对方的胸，原来他们就是景区啊。", "①、==P(plan)—软件规格说明==。规定软件的功能及其运行时的限制。", "②、==D(do)—软件开发==。产生满足规格说明的软件。", "③、==C(check)—软件确认==。确认软件能够满足客户提出的要求。", "④、==A(action)--软件演进==。为满足客户的变更要求，软件必须在使用的过程中演进。", "7、软件工程模型与==软件生命周期==", "（1）软件工程模型：也称软件开发模型，它是软件开发全部过程、活动和任务的结构框架。", "（2）典型模型：瀑布模型、增量模型、原型模型、喷泉模型、V 模型等", "==（3）软件生命周期（==@@三个时期八个阶段@@==）：定义期（可行性分析、需求分析）、开发期（概要设计、详细设计、编码、测试）、维护期（运行与维护、退役）。如下图所示。=="]}, {"t": "img", "id": "a2-2-5-1-b2", "imp": "normal", "src": "/kb-assets/theory/p46_r0_5b2643031848cb4d.png", "w": 2000, "h": 1138, "title": ""}, {"t": "list", "id": "a2-2-5-1-b3", "imp": "core", "title": "", "ordered": false, "items": ["①、==瀑布模型==：顺序清晰，一般==需求比较明确==，面向过程（结构化）开发。"]}, {"t": "img", "id": "a2-2-5-1-b4", "imp": "normal", "src": "/kb-assets/theory/p46_r1_679bfc278d4ceba4.png", "w": 1546, "h": 768, "title": ""}, {"t": "list", "id": "a2-2-5-1-b5", "imp": "core", "items": ["②、==增量模型==：增量模型是将整个模型分为多个子开发阶段的开发模型，其中每个开发阶段的相应测试阶段都是实践。对所开发的领域比较熟悉而且已有原型系统，进行==已有产品升级或新版本开发==等时候比较适合。"], "title": "", "ordered": false}, {"h": 397, "t": "img", "w": 817, "id": "a2-2-5-1-b6", "imp": "normal", "src": "/kb-assets/theory/p47_r0_f883ae474fdee0f3.png", "title": ""}, {"t": "list", "id": "a2-2-5-1-b7", "imp": "core", "title": "", "ordered": false, "items": ["③、==原型模型==：原型模型采用逐步求精的方法完善原型，使得原型能够“快速”开发，避免了像瀑布模型一样在冗长的开发过程中难以==对用户的反馈作出快速的响应==。==原型模型适用于那些不能预先确切定义需求的软件系统的开发。=="]}, {"h": 414, "t": "img", "w": 464, "id": "a2-2-5-1-b8", "imp": "normal", "src": "/kb-assets/theory/p47_r1_fe50266c5b4626a7.png", "title": ""}, {"t": "list", "id": "a2-2-5-1-b9", "imp": "core", "title": "", "ordered": false, "items": ["④、==喷泉模型==：喷泉模型是一种==以用户需求为动力，以对象为驱动的模型==，主要用于描述面向对象的软件开发过程。适应于==面向对象的软件开发过程==。"]}, {"h": 466, "t": "img", "w": 328, "id": "a2-2-5-1-b10", "imp": "normal", "src": "/kb-assets/theory/p47_r2_a8b2edea140d7e62.png", "title": ""}, {"t": "list", "id": "a2-2-5-1-b11", "imp": "core", "title": "", "ordered": false, "items": ["⑤、==V 模型==：==瀑布模型的变种，它反映了测试活动与分析和设计的关系。模式是一种传统软件开发模型，一般适用于一些传统信息系统应用的开发。=="]}, {"h": 452, "t": "img", "w": 890, "id": "a2-2-5-1-b12", "imp": "normal", "src": "/kb-assets/theory/p48_r0_0d1590eba860b3c3.png", "title": ""}, {"t": "list", "id": "a2-2-5-1-b13", "imp": "core", "title": "", "ordered": false, "items": ["8、==软件发展阶段、软件危机与软件工程要点==：软件发展的第一阶段以银行系统为代表，程序系统阶段（20世纪60—70年代）之后进入软件工程阶段（第三阶段）。 软件危机产生于20世纪60年代，表现为成本和进度估计不准确、用户不满意、难以维护、需求变化跟不上；原因在于软件自身复杂性（逻辑部件、规模庞大）及不正确的开发与维护方式（忽视需求分析、缺乏质量和进度控制、轻视维护）；消除软件危机应采用系统工程的管理方法以及软件开发技术与方法；软件开发包括==系统分析、系统开发、系统维护==。 软件工程（1968年10月由鲍尔等人在 NATO 会议提出）是摆脱软件危机的出路，其定义为应用于==计算机软件的定义、开发和维护的一整套方法、工具、文档、实践标准和工序==；其中定义期（计划期）先进行==系统规划、可行性研究与需求分析==，运行与维护阶段是==软件生命周期中最长、花费成本最高的部分==。", "9、==信息系统开发方法==：", "① ^^结构化生命周期方法。信息系统的生命周期^^：==信息系统从规划开始==，经过分析、设计、实施直到投入运行使用，在使用过程中随其生存环境的变化而不断修改，当不再适应需要时被淘汰，由新的信息系统代替，这种循环称为信息系统的生命周期，即规划、分析、设计、实施、运行、淘汰。结构化方法将信息系统生命周期分为系统规划、系统分析、系统设计、系统实施和系统维护5个阶段，各阶段工作按顺序开展，形如自上而下的瀑布，故又称瀑布模型方法。其分析和设计原则是自顶向下、逐层分解求精；系统分析阶段明确系统的结构和功能（做什么），系统设计阶段确定如何实现（怎么做）。", "② ^^原型法^^：分析设计人员与用户合作，在短期内定义用户基本需求的基础上，先开发出一个具备基本功能、实验性的、简易的应用软件，运行该原型并在辅助开发工具支持下，按不断求优的设计思想反复完善，最终开发出符合用户要求的信息系统。", "③ 面向对象方法。", "④ CASE 软件工程方法。", "10、信息系统开发方法的发展过程"]}, {"t": "table", "id": "a2-2-5-1-b14", "imp": "core", "title": "", "headers": ["年代", "20 世纪 70 年代", "20 世纪 80 年代", "20 世纪 90 年代"], "rows": [["程序设计方法", "==SP 方法==、JSP 方法", "", ""], ["软件工程方法", "SADT 方法、JSD 方法", "prototyping 方法", "==OO 方法=="], ["管理/需求分析", "SRD 方法、BSP 方法", "CSFs 方法", ""], ["自动化开发方法", "", "", "CASE 方法"]]}, {"t": "list", "id": "a2-2-5-1-b15", "imp": "core", "title": "", "ordered": false, "items": ["SP（Structured Program）为结构化程序方法，JSP（Jackson Structured Program）为杰克逊结构程序方法，JSD（Jackson System Development）为杰克逊系统开发方法，SADT（Structured Analysis & Design Technology）为结构化系统分析与设计技术，prototyping 为原型方法，OO（Object Oriented）为面向对象的开发方法，SRD（Structured Requirements Definition）为结构化需求定义方法，BSP（Business Systems Planning）为商业系统规划法，CSFs（Critical Success Factors）为关键成功因子法，CASE（Computer Aided Software Engineering）为计算机辅助软件工程方法。"]}, {"t": "callout", "id": "a2-2-5-1-b16", "imp": "core", "kind": "tip", "text": "20 世纪 60 年代爆发“软件危机”（开发成本失控、进度严重拖期、质量低下、维护极其困难）；为消除软件危机，==1968 年北大西洋公约组织（NATO）国际会议正式提出“软件工程（Software Engineering）”概念==，强调将工程化、规范化、可度量的方法应用于软件的开发和维护中。", "title": "考向复习提示：软件危机与软件工程诞生"}, {"t": "callout", "id": "a2-2-5-1-b17", "imp": "core", "kind": "tip", "text": "• ==瀑布模型（Waterfall Model）==：阶段间严格顺序流动，上一阶段产出作为下一阶段输入，文档驱动，适用于需求明确固定且不频繁变动的项目； • ==原型模型与敏捷开发（Agile/Scrum）==：以人为核心、迭代轻量、紧密拥抱需求变化，能迅速交付可运行的软件增量。", "title": "考向复习提示：传统瀑布模型 vs 敏捷开发模型"}, {"t": "callout", "id": "a2-2-5-1-b18", "imp": "core", "kind": "trap", "text": "专转本必考题：整个软件生命周期通常划分为可行性研究与规划、需求分析、设计、编码、测试和运行维护六大阶段；其中==消耗人力、时间与资金成本最高（通常占总成本 60% ~ 80%）的阶段是“运行与维护阶段”==，绝不是很多考生直觉以为的“编写代码”阶段！", "title": "高频易错陷阱：软件生命周期中花费成本最高的阶段"}]$b87$::jsonb;
  v_search text := $s87$A2-2.5.1 软件工程基本概念与生命周期。 1、软件危机：软件危机泛指在计算机软件的开发和维护过程中遇到的一系列严重的问题，集中表现在成本，质量，生产效率等几个方面。 2、软件工程 （1）软件工程是指采用工程的概念、原理、技术和方法指导软件的开发与维护。 （2）软件工程的主要思想强调在软件开发过程中需要应用工程化原则。 （3）软件工程的核心思想是把软件当作一个工程产品来处理。 3、软件工程三要素：方法、工具、过程。 记忆口诀： 阮三要（软件工程三大要素）一要芳芳（方法）为爱情，二要工作（工具）为事业，三要过日子（过程）为生活。 （1）方法：方法是完成软件工程项目的技术手段；为软件开发提供“如何做”的技术。 （2）工具：工具支持软件的开发、管理、文档生成；提供的自动的或半自动的软件工程的支撑环境。 （3）过程：过程支持软件开发的各个环节的控制、管理；获得高质量的软件所需要完成的一系列任务的框架。 4、软件工程的目标（七大目标）： 记忆口诀：阮七目（可移植性）靠（可靠性）维（可维护性）修（可修改性）重（可重用）新追（可追踪性）你（可理解性） （1）可修改性：允许对系统进行修改而不增加原系统的复杂性。它支持软件的调试和维护，是一个难以达到的目标。 （2）可靠性：能防止因概念、设计和结构等方面的不完善造成的软件系统失效，具有挽回因操作不当造成软件系统失效的能力。 （3）可理解性：系统具有清晰的结构，能直接反映问题的需求。可理解性有助于控制系统软件复杂性，并支持软件的维护、移植或重用。 （4）可维护性：软件交付使用后，能够对它进行修改，以改正潜伏的错误，改进性能和其它属性，使软件产品适应环境的变化等。软件维护费用在软件开发费用中占有很大的比重。可维护性是软件工程中一项十分重要的目标。 （5）可重用性：把概念或功能相对独立的一个或一组相关模块定义为一个软部件。可组装在系统的任何位置，降低工作量。 （6）可移植性：软件从一个计算机系统或环境搬到另一个计算机系统或环境的难易程度。 （7）可追踪性：根据软件需求对软件设计、程序进行正向追踪，或根据软件设计、程序对软件需求的逆向追踪的能力。 5、软件工程原则（八大原则）： 记忆口诀： 阮八原（软件工程八大原则）居（局部化）然相信（信息隐藏）一（一致性）碗（完备性） 馍（模块化）会因为缺（确定性）一克盐（可验证性）变臭（抽象）了。 （1）抽象：采用分层次抽象，自顶向下、逐层细化的办法控制软件开发过程的复杂性。 （2）模块化：模块化有助于信息隐蔽和抽象，有助于表示复杂的系统。 模块化的独立性：耦合度和内聚度是衡量软件模块独立性的主要标准，软件设计应尽量做到高内聚，低耦合（高内聚低耦合是判断软件设计好坏的标准）。 ①、内聚：模块内部的紧密程度，模块内部联系越紧，模块与模块之间的耦合就会越低。 ②、耦合：模块与模块之间的联系或关联程度。 （3）信息隐蔽：将模块设计成"黑箱"，实现的细节隐藏在模块内部，不让模块的使用者直接访问，这就是信息封装。 （4）局部化：保证模块之间具有松散的耦合，模块内部具有较强的内聚，这有助于控制解的复杂性。 （5）确定性：软件开发过程中所有概念的表达应是确定的、无歧义性的、规范的。 （6）一致性：整个软件系统使用一致的概念、符号和术语。 （7）完备性：软件系统不丢失任何重要成分，可以完全实现系统所要求功能的程度。 （8）可验证性：易于检查、测试、评审，确保系统的正确性。 6、软件工程过程 （1）软件工程过程是把软件转化为输出的一组彼此相关的资源活动 （2）软件工程过程的四个基本活动： 记忆口诀： 阮四基（软件工程的过程中四个基本活动） 一基小猪佩奇计划找1P（Plan，软件规格说明）,一起看2D(Do，软件开发)动画,发现没有安全的3C(Check，软件确认)电子产品，最后决定去4A(Action，软件演进)级景区玩，忽然两人互相看看了对方的胸，原来他们就是景区啊。 ①、P(plan)—软件规格说明。规定软件的功能及其运行时的限制。 ②、D(do)—软件开发。产生满足规格说明的软件。 ③、C(check)—软件确认。确认软件能够满足客户提出的要求。 ④、A(action)--软件演进。为满足客户的变更要求，软件必须在使用的过程中演进。 7、软件工程模型与软件生命周期 （1）软件工程模型：也称软件开发模型，它是软件开发全部过程、活动和任务的结构框架。 （2）典型模型：瀑布模型、增量模型、原型模型、喷泉模型、V 模型等 （3）软件生命周期（三个时期八个阶段）：定义期（可行性分析、需求分析）、开发期（概要设计、详细设计、编码、测试）、维护期（运行与维护、退役）。如下图所示。 ①、瀑布模型：顺序清晰，一般需求比较明确，面向过程（结构化）开发。 ②、增量模型：增量模型是将整个模型分为多个子开发阶段的开发模型，其中每个开发阶段的相应测试阶段都是实践。对所开发的领域比较熟悉而且已有原型系统，进行已有产品升级或新版本开发等时候比较适合。 ③、原型模型：原型模型采用逐步求精的方法完善原型，使得原型能够“快速”开发，避免了像瀑布模型一样在冗长的开发过程中难以对用户的反馈作出快速的响应。原型模型适用于那些不能预先确切定义需求的软件系统的开发。 ④、喷泉模型：喷泉模型是一种以用户需求为动力，以对象为驱动的模型，主要用于描述面向对象的软件开发过程。适应于面向对象的软件开发过程。 ⑤、V 模型：瀑布模型的变种，它反映了测试活动与分析和设计的关系。模式是一种传统软件开发模型，一般适用于一些传统信息系统应用的开发。 8、软件发展阶段、软件危机与软件工程要点：软件发展的第一阶段以银行系统为代表，程序系统阶段（20世纪60—70年代）之后进入软件工程阶段（第三阶段）。 软件危机产生于20世纪60年代，表现为成本和进度估计不准确、用户不满意、难以维护、需求变化跟不上；原因在于软件自身复杂性（逻辑部件、规模庞大）及不正确的开发与维护方式（忽视需求分析、缺乏质量和进度控制、轻视维护）；消除软件危机应采用系统工程的管理方法以及软件开发技术与方法；软件开发包括系统分析、系统开发、系统维护。 软件工程（1968年10月由鲍尔等人在 NATO 会议提出）是摆脱软件危机的出路，其定义为应用于计算机软件的定义、开发和维护的一整套方法、工具、文档、实践标准和工序；其中定义期（计划期）先进行系统规划、可行性研究与需求分析，运行与维护阶段是软件生命周期中最长、花费成本最高的部分。 9、信息系统开发方法： ① 结构化生命周期方法。信息系统的生命周期：信息系统从规划开始，经过分析、设计、实施直到投入运行使用，在使用过程中随其生存环境的变化而不断修改，当不再适应需要时被淘汰，由新的信息系统代替，这种循环称为信息系统的生命周期，即规划、分析、设计、实施、运行、淘汰。结构化方法将信息系统生命周期分为系统规划、系统分析、系统设计、系统实施和系统维护5个阶段，各阶段工作按顺序开展，形如自上而下的瀑布，故又称瀑布模型方法。其分析和设计原则是自顶向下、逐层分解求精；系统分析阶段明确系统的结构和功能（做什么），系统设计阶段确定如何实现（怎么做）。 ② 原型法：分析设计人员与用户合作，在短期内定义用户基本需求的基础上，先开发出一个具备基本功能、实验性的、简易的应用软件，运行该原型并在辅助开发工具支持下，按不断求优的设计思想反复完善，最终开发出符合用户要求的信息系统。 ③ 面向对象方法。 ④ CASE 软件工程方法。 10、信息系统开发方法的发展过程 年代 20 世纪 70 年代 20 世纪 80 年代 20 世纪 90 年代 程序设计方法 SP 方法、JSP 方法 软件工程方法 SADT 方法、JSD 方法 prototyping 方法 OO 方法 管理/需求分析 SRD 方法、BSP 方法 CSFs 方法 自动化开发方法 CASE 方法 SP（Structured Program）为结构化程序方法，JSP（Jackson Structured Program）为杰克逊结构程序方法，JSD（Jackson System Development）为杰克逊系统开发方法，SADT（Structured Analysis & Design Technology）为结构化系统分析与设计技术，prototyping 为原型方法，OO（Object Oriented）为面向对象的开发方法，SRD（Structured Requirements Definition）为结构化需求定义方法，BSP（Business Systems Planning）为商业系统规划法，CSFs（Critical Success Factors）为关键成功因子法，CASE（Computer Aided Software Engineering）为计算机辅助软件工程方法。 考向复习提示：软件危机与软件工程诞生 20 世纪 60 年代爆发“软件危机”（开发成本失控、进度严重拖期、质量低下、维护极其困难）；为消除软件危机，1968 年北大西洋公约组织（NATO）国际会议正式提出“软件工程（Software Engineering）”概念，强调将工程化、规范化、可度量的方法应用于软件的开发和维护中。 考向复习提示：传统瀑布模型 vs 敏捷开发模型 • 瀑布模型（Waterfall Model）：阶段间严格顺序流动，上一阶段产出作为下一阶段输入，文档驱动，适用于需求明确固定且不频繁变动的项目； • 原型模型与敏捷开发（Agile/Scrum）：以人为核心、迭代轻量、紧密拥抱需求变化，能迅速交付可运行的软件增量。 高频易错陷阱：软件生命周期中花费成本最高的阶段 专转本必考题：整个软件生命周期通常划分为可行性研究与规划、需求分析、设计、编码、测试和运行维护六大阶段；其中消耗人力、时间与资金成本最高（通常占总成本 60% ~ 80%）的阶段是“运行与维护阶段”，绝不是很多考生直觉以为的“编写代码”阶段！$s87$;
  v_sr jsonb := $r87${"pdf": "理论复习.pdf", "pages": [44, 45, 46, 47, 48, 53], "spans": 66, "extra": ["考纲三级节点: A2-2.5.1 软件工程基本概念与生命周期。", "题库补充：软件发展阶段、软件危机与软件工程要点", "题库补充：信息系统开发方法 (46题)"]}$r87$::jsonb;
begin
  select r.rev_no, r.html
    into old_rev
    from kb_entry e
    join kb_revision r on r.node_id = e.node_id and r.rev_no = e.published_rev
   where e.node_id = 87;

  if not found then
    raise exception 'node 87 找不到已发布 revision';
  end if;
  if old_rev.rev_no <> 2 then
    raise exception 'node 87 expected rev 2, got %', old_rev.rev_no;
  end if;

  select coalesce(max(rev_no), 0) + 1 into v_rev
    from kb_revision
   where node_id = 87;

  insert into kb_revision (node_id, rev_no, blocks, html, search_text, source_ref)
  values (87, v_rev, v_blocks, old_rev.html, v_search, v_sr);

  update kb_entry
     set published_rev = v_rev,
         updated_at = now()
   where node_id = 87;
end $$;

do $$
declare
  old_rev record;
  v_rev integer;
  v_blocks jsonb := $b88$[{"t": "list", "id": "a2-2-5-2-b1", "imp": "important", "title": "", "ordered": false, "items": ["1、需求分析概述", "（1）^^需求分析阶段的工作：需求获取，需求分析，编写需求规格说明书，需求评审。^^", "（2）结构化需求分析方法：", "^^①、面向数据结构的 Jackson 方法（JSD）^^", "^^②、面向数据流的结构化分析方法（SA）^^", "^^③、面向数据结构的结构化数据系统开发方法（DSSD）^^", "（3）^^面向对象分析与设计原则（OOA/OOD 常考属性）：抽象，信息隐蔽，模块化，局部化，确定性，一致性，完备性，可验证性。^^", "（4）^^软件需求规格说明书（SRS，Software Requirement Specification）是需求分析阶段得出的最主要的文档。^^软件需求规格说明书的特点：有正确性、无歧义性、完整性、可验证性、一致性、可理解性、可修改性和可追踪性。其中最重要的是无歧义性。", "2、结构化分析与设计", "（1）^^结构化方法包括结构化分析方法，结构化设计方法，结构化编程方法。^^", "（2）^^结构化方法中，软件功能分解属于总体设计阶段。^^", "（3）结构化分析方法是面向数据流自顶而下逐步求精进行需求分析的方法。", "（4）结构化分析方法在软件需求分析阶段的应用。", "（5）结构化分析的常用工具：", "①、^^数据流图(DFD)^^：箭头、圆或椭圆、双横、方框"]}, {"h": 360, "t": "img", "w": 882, "id": "a2-2-5-2-b2", "imp": "normal", "src": "/kb-assets/theory/p48_r1_6a20283fe16a4e72.png", "title": ""}, {"t": "list", "id": "a2-2-5-2-b3", "imp": "important", "items": ["②、^^数据字典(DD)^^：数据流、数据流分量、数据存储、处理", "③、^^判定树（决策树）^^："], "title": "", "ordered": false}, {"h": 430, "t": "img", "w": 944, "id": "a2-2-5-2-b4", "imp": "normal", "src": "/kb-assets/theory/p49_r0_f7c7d85bcae4a589.png", "title": ""}, {"t": "list", "id": "a2-2-5-2-b5", "imp": "important", "items": ["④、^^判定表^^："], "title": "", "ordered": false}, {"h": 368, "t": "img", "w": 971, "id": "a2-2-5-2-b6", "imp": "normal", "src": "/kb-assets/theory/p49_r1_ceef6af33a53d95e.png", "title": ""}, {"t": "list", "id": "a2-2-5-2-b7", "imp": "core", "title": "", "ordered": false, "items": ["3、==结构化设计（概要设计与详细设计）==", "（1）==概要设计(总体设计)：将软件需求转化为软件体系结构、确定系统级接口、全局数据结构或数据库模式；==", "①、任务：划分出组成系统的物理元素、设计软件的结构；", "②、工具：==结构图（程序结构图）、面向数据流设计==。", "③、产物：==概要设计说明书==", "（2）==详细设计：确立每个模块的实现算法和局部数据结构，用适当方法表示算法和数据结构的细节。==", "①、任务：==详细设计的主要任务是设计每个模块的实现算法、所需的局部数据结构。==", "②、工具：==图形工具（程序流程图、N-S 图、PAD 图）、表格工具（判定表）、语言工具（PDL—过程设计语言）=="]}, {"h": 678, "t": "img", "w": 905, "id": "a2-2-5-2-b8", "imp": "normal", "src": "/kb-assets/theory/p50_r0_41605df4e7e10f03.png", "title": ""}, {"t": "list", "id": "a2-2-5-2-b9", "imp": "core", "title": "", "ordered": false, "items": ["③、产物：==详细设计说明书==", "4、==结构化设计方法与总体设计、详细设计==：结构化设计方法（SD，Structured Design）是基于模块化、自顶向下逐步细化、结构化程序设计等程序设计技术发展起来的。 基本思想：将软件设计成由相对独立且具有单一功能的模块组成的结构，分为==概要设计和详细设计两个阶段==。概要设计阶段的描述工具是结构图（SC）。 概要设计也称结构设计或总体设计，主要任务是把系统的功能需求分配给软件结构，形成软件的模块结构图。 结构图是软件结构概要设计阶段的工具，反映系统的功能实现以及模块与模块之间的联系与通信，即反映系统的总体结构。", "5、==软件功能分解所属的开发阶段==：软件功能分解（模块划分）属于软件开发中的总体设计（概要设计）阶段。", "6、^^计算机软件技术^^：==计算机软件技术包括==：软件工程技术、软件设计技术、软件工具环境技术、系统软件技术、数据库技术、网络软件技术、与实际工作相关的软件技术。", "7、^^系统分析与系统设计的任务^^：^^系统分析阶段明确系统的结构和功能（做什么）^^，系统设计阶段确定其如何实现（怎么做）。"]}, {"t": "callout", "id": "a2-2-5-2-b10", "imp": "core", "kind": "trap", "text": "衡量模块独立性的核心原则是：==“高内聚、低耦合（High Cohesion, Low Coupling）”==； • ==内聚性（Cohesion）==度量模块内部各个元素结合的紧密程度，==功能内聚最高、偶然内聚最低==； • ==耦合性（Coupling）==度量模块之间相互联系依赖的紧密程度，==非直接耦合最弱（最好）、内容耦合最强（最差）==；考试常考颠倒两者的高低优劣要求！", "title": "高频易错陷阱：模块独立性两大度量指标（高内聚低耦合）"}]$b88$::jsonb;
  v_search text := $s88$A2-2.5.2 结构化设计方法，总体设计与详细设计。 1、需求分析概述 （1）需求分析阶段的工作：需求获取，需求分析，编写需求规格说明书，需求评审。 （2）结构化需求分析方法： ①、面向数据结构的 Jackson 方法（JSD） ②、面向数据流的结构化分析方法（SA） ③、面向数据结构的结构化数据系统开发方法（DSSD） （3）面向对象分析与设计原则（OOA/OOD 常考属性）：抽象，信息隐蔽，模块化，局部化，确定性，一致性，完备性，可验证性。 （4）软件需求规格说明书（SRS，Software Requirement Specification）是需求分析阶段得出的最主要的文档。软件需求规格说明书的特点：有正确性、无歧义性、完整性、可验证性、一致性、可理解性、可修改性和可追踪性。其中最重要的是无歧义性。 2、结构化分析与设计 （1）结构化方法包括结构化分析方法，结构化设计方法，结构化编程方法。 （2）结构化方法中，软件功能分解属于总体设计阶段。 （3）结构化分析方法是面向数据流自顶而下逐步求精进行需求分析的方法。 （4）结构化分析方法在软件需求分析阶段的应用。 （5）结构化分析的常用工具： ①、数据流图(DFD)：箭头、圆或椭圆、双横、方框 ②、数据字典(DD)：数据流、数据流分量、数据存储、处理 ③、判定树（决策树）： ④、判定表： 3、结构化设计（概要设计与详细设计） （1）概要设计(总体设计)：将软件需求转化为软件体系结构、确定系统级接口、全局数据结构或数据库模式； ①、任务：划分出组成系统的物理元素、设计软件的结构； ②、工具：结构图（程序结构图）、面向数据流设计。 ③、产物：概要设计说明书 （2）详细设计：确立每个模块的实现算法和局部数据结构，用适当方法表示算法和数据结构的细节。 ①、任务：详细设计的主要任务是设计每个模块的实现算法、所需的局部数据结构。 ②、工具：图形工具（程序流程图、N-S 图、PAD 图）、表格工具（判定表）、语言工具（PDL—过程设计语言） ③、产物：详细设计说明书 4、结构化设计方法与总体设计、详细设计：结构化设计方法（SD，Structured Design）是基于模块化、自顶向下逐步细化、结构化程序设计等程序设计技术发展起来的。 基本思想：将软件设计成由相对独立且具有单一功能的模块组成的结构，分为概要设计和详细设计两个阶段。概要设计阶段的描述工具是结构图（SC）。 概要设计也称结构设计或总体设计，主要任务是把系统的功能需求分配给软件结构，形成软件的模块结构图。 结构图是软件结构概要设计阶段的工具，反映系统的功能实现以及模块与模块之间的联系与通信，即反映系统的总体结构。 5、软件功能分解所属的开发阶段：软件功能分解（模块划分）属于软件开发中的总体设计（概要设计）阶段。 6、计算机软件技术：计算机软件技术包括：软件工程技术、软件设计技术、软件工具环境技术、系统软件技术、数据库技术、网络软件技术、与实际工作相关的软件技术。 7、系统分析与系统设计的任务：系统分析阶段明确系统的结构和功能（做什么），系统设计阶段确定其如何实现（怎么做）。 高频易错陷阱：模块独立性两大度量指标（高内聚低耦合） 衡量模块独立性的核心原则是：“高内聚、低耦合（High Cohesion, Low Coupling）”； • 内聚性（Cohesion）度量模块内部各个元素结合的紧密程度，功能内聚最高、偶然内聚最低； • 耦合性（Coupling）度量模块之间相互联系依赖的紧密程度，非直接耦合最弱（最好）、内容耦合最强（最差）；考试常考颠倒两者的高低优劣要求！$s88$;
  v_sr jsonb := $r88${"pdf": "理论复习.pdf", "pages": [48, 49, 50], "spans": 32, "extra": ["考纲三级节点: A2-2.5.2 结构化设计方法，总体设计与详细设计。", "题库补充：结构化设计方法与总体设计、详细设计 (102题)", "题库补充：软件功能分解所属的开发阶段 (28题)", "题库补充：计算机软件技术 (7题)", "题库补充：系统分析与系统设计的任务 (7题)"]}$r88$::jsonb;
begin
  select r.rev_no, r.html
    into old_rev
    from kb_entry e
    join kb_revision r on r.node_id = e.node_id and r.rev_no = e.published_rev
   where e.node_id = 88;

  if not found then
    raise exception 'node 88 找不到已发布 revision';
  end if;
  if old_rev.rev_no <> 4 then
    raise exception 'node 88 expected rev 4, got %', old_rev.rev_no;
  end if;

  select coalesce(max(rev_no), 0) + 1 into v_rev
    from kb_revision
   where node_id = 88;

  insert into kb_revision (node_id, rev_no, blocks, html, search_text, source_ref)
  values (88, v_rev, v_blocks, old_rev.html, v_search, v_sr);

  update kb_entry
     set published_rev = v_rev,
         updated_at = now()
   where node_id = 88;
end $$;

do $$
declare
  old_rev record;
  v_rev integer;
  v_blocks jsonb := $b89$[{"t": "list", "id": "a2-2-5-3-b1", "imp": "core", "title": "", "ordered": false, "items": ["1、==面向对象分析与设计==", "（1）==面向对象分析（OOA）: 确定需求或者业务的角度，按照面向对象的思想来分析业务。==", "（2）面向对象分析五个活动：认定对象、组织对象、描述对象的相互作用、确定对象的操作、定义对象的内部信息。", "①、认定对象：在应用领域中，按自然存在的实体确立对象。", "②、组织对象：分析对象间的关系，抽象出类，简化关联对象，建立层次结构等", "③、对象间的相互作用：描述各对象在系统中的关系，得出对象的界面描述。", "④、基本对象的操作：对象的操作可以是简单的（创建，增加和删除等）;也有复杂的操作（多个对象信息的连接）；确定对象操作后，进行定义对象的内部，包括内部数据信息、信息存储方法、继承关系以及可能生成的实例数等属性。", "（3）==面向对象设计：设计阶段考虑与实现有关的因素，对OOA 模型进行调整并补充与实现有关的部分，形成OOD 模型。==包括四个部件，即人机交互部件、问题域部件、任务管理部件和数据管理部件。", "①、设计人机交互部件", "②、设计问题域部件", "③、设计任务管理部件", "④、设计数据管理部件", "（4）==面向对象分析与设计工具：UML==", "==①、UML(Unified Modeling Language): 用于系统的可视化建模语言，是一种用于软件蓝图的标准语言，可用于详细描述的语言，是一种构造语言，也是一种文档化语言。==", "==②、作用：为软件系统建立可视化模型；为软件系统建立构件；为软件系统建立文档。==", "==③、主要的模型：功能模型（用例图）、对象模型（对象图、类图）、动态模型（序列图、活动图、状态图）。==", "==④、UML 由模型元素（类、对象、消息等）、图（元素集图形表示）、视图（系统的抽象表示）和通用机制（注释、模型元素的语义等）等几个部分组成。==", "==⑤、UML 图：用例图、类图、对象图、序列图、协作图、状态图、活动图、部署图、构件图。==", "==⑥、UML 常见关系：UML 常见的六种关系图标：泛化（继承）、实现（接口）、关联（比如学生、课程和课程表）、聚合（比如汽车、引擎和轮胎）、组合（比如公司和部门）、依赖（比如现代人和计算机之间操作）==", "==⑦、UML 是一种建模语言，不是一种方法，不包括过程的概念，本身是独立于过程的。==", "2、==面向对象方法的三个重要特征==：^^面向对象方法的三个重要特征^^：==封装、继承、多态==。", "3、==SOA 面向服务架构的基本概念==：SOA（Service-Oriented Architecture，面向服务的架构）是一个组件模型，它将应用程序的不同功能单元（称为服务）通过这些服务之间定义良好的接口和契约联系起来。接口采用中立的方式进行定义，应该独立于实现服务的硬件平台、操作系统和编程语言。这使得构建在各种各样的系统中的服务可以以一种统一和通用的方式进行交互。面向服务架构可以根据需求，通过网络对松散耦合的粗粒度应用组件进行分布式部署、组合和使用。服务层是SOA的基础，可以直接被应用调用，从而有效控制系统中与软件代理交互的人为依赖性。", "4、^^类的定义与组成（UML 类图）^^：类是对一组具有相同属性、操作、关联的对象的抽象，是面向对象系统组织结构的核心。类包括^^名称、属性和操作三部分^^。以「学生」类为例：名称为学生，属性为姓名（string），操作为学习()。", "5、^^面向对象方法的优点^^：", "① ^^与人类的思维习惯和方法一致^^。", "② ^^稳定性好^^。", "③ ^^可重用性好^^。", "④ ^^可维护性好^^。", "⑤ ^^易于开发大型软件^^。", "6、^^面向对象模型与关系数据模型的转换^^：^^面向对象模型^^；现实世界对象转换到关系数据模型，从关系概念模型（结构）入手。"]}, {"t": "callout", "id": "a2-2-5-3-b2", "imp": "core", "kind": "tip", "text": "面向对象分析（OOA）关键在于抽取问题域的对象与用例；面向对象设计（OOD）将分析模型转化为系统架构，核心采用 ==UML（统一建模语言）==进行可视化建模；核心设计原则包括：==单一职责原则（SRP）、开闭原则（OCP，对扩展开放对修改关闭）、里氏替换原则（LSP）、依赖倒置原则（DIP）与接口隔离原则（ISP）==。", "title": "考向复习提示：面向对象分析与设计核心原则"}, {"t": "callout", "id": "a2-2-5-3-b3", "imp": "core", "kind": "trap", "text": "专转本必考题辨析：==UML（Unified Modeling Language）是一种面向对象的图形化“建模语言”或“表达规范”，绝对不是可编译执行的“编程语言”==！UML 独立于具体的编程语言，无论后续使用 Java、C++ 还是 Python 均可采用 UML 进行先期系统分析与架构设计。", "title": "高频易错陷阱：UML 属于建模语言而非编程语言"}]$b89$::jsonb;
  v_search text := $s89$A2-2.5.3 面向对象分析与设计：OOD，UML 图。 1、面向对象分析与设计 （1）面向对象分析（OOA）: 确定需求或者业务的角度，按照面向对象的思想来分析业务。 （2）面向对象分析五个活动：认定对象、组织对象、描述对象的相互作用、确定对象的操作、定义对象的内部信息。 ①、认定对象：在应用领域中，按自然存在的实体确立对象。 ②、组织对象：分析对象间的关系，抽象出类，简化关联对象，建立层次结构等 ③、对象间的相互作用：描述各对象在系统中的关系，得出对象的界面描述。 ④、基本对象的操作：对象的操作可以是简单的（创建，增加和删除等）;也有复杂的操作（多个对象信息的连接）；确定对象操作后，进行定义对象的内部，包括内部数据信息、信息存储方法、继承关系以及可能生成的实例数等属性。 （3）面向对象设计：设计阶段考虑与实现有关的因素，对OOA 模型进行调整并补充与实现有关的部分，形成OOD 模型。包括四个部件，即人机交互部件、问题域部件、任务管理部件和数据管理部件。 ①、设计人机交互部件 ②、设计问题域部件 ③、设计任务管理部件 ④、设计数据管理部件 （4）面向对象分析与设计工具：UML ①、UML(Unified Modeling Language): 用于系统的可视化建模语言，是一种用于软件蓝图的标准语言，可用于详细描述的语言，是一种构造语言，也是一种文档化语言。 ②、作用：为软件系统建立可视化模型；为软件系统建立构件；为软件系统建立文档。 ③、主要的模型：功能模型（用例图）、对象模型（对象图、类图）、动态模型（序列图、活动图、状态图）。 ④、UML 由模型元素（类、对象、消息等）、图（元素集图形表示）、视图（系统的抽象表示）和通用机制（注释、模型元素的语义等）等几个部分组成。 ⑤、UML 图：用例图、类图、对象图、序列图、协作图、状态图、活动图、部署图、构件图。 ⑥、UML 常见关系：UML 常见的六种关系图标：泛化（继承）、实现（接口）、关联（比如学生、课程和课程表）、聚合（比如汽车、引擎和轮胎）、组合（比如公司和部门）、依赖（比如现代人和计算机之间操作） ⑦、UML 是一种建模语言，不是一种方法，不包括过程的概念，本身是独立于过程的。 2、面向对象方法的三个重要特征：面向对象方法的三个重要特征：封装、继承、多态。 3、SOA 面向服务架构的基本概念：SOA（Service-Oriented Architecture，面向服务的架构）是一个组件模型，它将应用程序的不同功能单元（称为服务）通过这些服务之间定义良好的接口和契约联系起来。接口采用中立的方式进行定义，应该独立于实现服务的硬件平台、操作系统和编程语言。这使得构建在各种各样的系统中的服务可以以一种统一和通用的方式进行交互。面向服务架构可以根据需求，通过网络对松散耦合的粗粒度应用组件进行分布式部署、组合和使用。服务层是SOA的基础，可以直接被应用调用，从而有效控制系统中与软件代理交互的人为依赖性。 4、类的定义与组成（UML 类图）：类是对一组具有相同属性、操作、关联的对象的抽象，是面向对象系统组织结构的核心。类包括名称、属性和操作三部分。以「学生」类为例：名称为学生，属性为姓名（string），操作为学习()。 5、面向对象方法的优点： ① 与人类的思维习惯和方法一致。 ② 稳定性好。 ③ 可重用性好。 ④ 可维护性好。 ⑤ 易于开发大型软件。 6、面向对象模型与关系数据模型的转换：面向对象模型；现实世界对象转换到关系数据模型，从关系概念模型（结构）入手。 考向复习提示：面向对象分析与设计核心原则 面向对象分析（OOA）关键在于抽取问题域的对象与用例；面向对象设计（OOD）将分析模型转化为系统架构，核心采用 UML（统一建模语言）进行可视化建模；核心设计原则包括：单一职责原则（SRP）、开闭原则（OCP，对扩展开放对修改关闭）、里氏替换原则（LSP）、依赖倒置原则（DIP）与接口隔离原则（ISP）。 高频易错陷阱：UML 属于建模语言而非编程语言 专转本必考题辨析：UML（Unified Modeling Language）是一种面向对象的图形化“建模语言”或“表达规范”，绝对不是可编译执行的“编程语言”！UML 独立于具体的编程语言，无论后续使用 Java、C++ 还是 Python 均可采用 UML 进行先期系统分析与架构设计。$s89$;
  v_sr jsonb := $r89${"pdf": "理论复习.pdf", "pages": [50, 51], "spans": 26, "extra": ["考纲三级节点: A2-2.5.3 面向对象分析与设计：OOD，UML 图。", "题库补充：面向对象方法的三个重要特征 (23题)", "题库补充：SOA 面向服务架构的基本概念 (21题)", "题库补充：类的定义与组成（UML 类图） (8题)", "题库补充：面向对象方法的优点 (7题)", "题库补充：面向对象模型与关系数据模型的转换 (7题)"]}$r89$::jsonb;
begin
  select r.rev_no, r.html
    into old_rev
    from kb_entry e
    join kb_revision r on r.node_id = e.node_id and r.rev_no = e.published_rev
   where e.node_id = 89;

  if not found then
    raise exception 'node 89 找不到已发布 revision';
  end if;
  if old_rev.rev_no <> 2 then
    raise exception 'node 89 expected rev 2, got %', old_rev.rev_no;
  end if;

  select coalesce(max(rev_no), 0) + 1 into v_rev
    from kb_revision
   where node_id = 89;

  insert into kb_revision (node_id, rev_no, blocks, html, search_text, source_ref)
  values (89, v_rev, v_blocks, old_rev.html, v_search, v_sr);

  update kb_entry
     set published_rev = v_rev,
         updated_at = now()
   where node_id = 89;
end $$;

do $$
declare
  old_rev record;
  v_rev integer;
  v_blocks jsonb := $b90$[{"t": "list", "id": "a2-2-5-4-b1", "imp": "core", "title": "", "ordered": false, "items": ["1、==软件测试==", "（1）==软件测试：为了发现错误而执行程序的过程，成功的测试是发现了至今尚未发现的错误的测试。==", "（2）==测试的目的就是希望能以最少的人力和时间发现潜在的各种错误和缺陷。==", "（3）一般软件测试分为：==单元测试、集成测试、系统测试和验收测试。==", "①、==单元测试==∶针对每个单元的测试，以确保每个模块能正常工作为目标。", "②、==集成测试==∶对已测试过的模块进行组装，进行集成测试，目的在于检验与软件设计相关的程序结构。", "③、==系统测试==∶检验软件产品能否与系统的其他部分（如硬件、数据库及操作人员）协调工作。", "④、==验收（用户）测试==∶检验软件产品质量的最后一道工序，主要突出用户的作用，同时软件开发人员也应有一定程度的参与。", "（4）测试方法分类：", "==①、从是否需要执行被测软件的角度分为静态测试和动态测试：==", "==静态测试包括代码检查、静态结构分析、代码质量度量，不实际运行软件，主要通过人工进行。==", "==动态测试是通过运行软件来检验软件中的动态行为和运行结果的正确性。==", "==②、按功能分为白盒测试和黑盒测试。==", "2、==白盒测试==", "==（1）白盒测试也称为结构测试或逻辑测试，是把程序看成装在一只透明的白盒子里，测试者完全了解程序的结构和处理过程。==它根据程序的内部逻辑来设计测试用例，检查程序中的逻辑通路是否都按预定的要求正确地工作。", "（2）基本原则：", "保证所测模块中每一独立路径至少执行一次。", "保证所测模块所有判断的每一分支至少执行一次。", "保证所测模块每一循环都在边界条件和一般条件下至少各执行一次。", "验证所有内部数据结构的有效性。", "按照白盒测试的基本原则，“白盒”法是穷举路径测试。", "（3）==白盒测试的方法：逻辑覆盖，基本路径测试==。", "（4）逻辑覆盖：语句覆盖、判定覆盖、条件覆盖、判定/条件覆盖、条件组合覆盖和路径覆盖发现错误的能力呈由弱至强的变化。", "语句覆盖：每条语句至少执行一次。", "判定覆盖：每个判定的每个分支至少执行一次。", "条件覆盖：每个判定的每个条件应取到各种可能的值。", "判定/条件覆盖：同时满足判定覆盖与条件覆盖。", "条件组合覆盖：每个判定中各条件的每一种组合至少出现一次。", "路径覆盖：使程序中每一条可能的路径至少执行一次。", "（5）基本路径测试：白盒测试的一种常用方法是基本路径法，根据源代码构造程序流程图，转换为控制流程图，得到基本路径，进而为每条基本路径设计测试用例。基本路径法的一个关键步骤是识别出所有的基本路径。"]}, {"h": 635, "t": "img", "w": 1192, "id": "a2-2-5-4-b2", "imp": "normal", "src": "/kb-assets/theory/p52_r0_822444884baca48c.png", "title": ""}, {"t": "list", "id": "a2-2-5-4-b3", "imp": "core", "title": "", "ordered": false, "items": ["3、==黑盒测试==", "==（1）黑盒测试也称功能测试或数据驱动测试，是把程序看成一只黑盒子，测试者完全不了解，或不考虑程序的结构和处理过程。它根据规格说明书的功能来设计测试用例，检查程序的功能是否符合规格说明的要求。==", "==（2）黑盒测试的方法：等价划分法，边界值分析法，错误推测法。==", "（3）等价划分法：这是一种典型的黑盒测试方法，它是将程序的所有可能的输入数据划分成若干部分(及若干等价类)，然后从每个等价类中选取数据作为测试用例。", "划分等价类：有效等价类、无效等价类"]}, {"h": 346, "t": "img", "w": 1352, "id": "a2-2-5-4-b4", "imp": "normal", "src": "/kb-assets/theory/p52_r1_6e3a40caae8e3b94.png", "title": ""}, {"t": "list", "id": "a2-2-5-4-b5", "imp": "normal", "title": "", "ordered": false, "items": ["（4）边界值分析法：它是对各种输入、输出范围的边界情况设计测试用例的方法。", "边界检验类型：数字、字符、位置、重量、大小、速度、方位、尺寸、空间等。", "例如：手机号的位数是 11 位。"]}, {"h": 244, "t": "img", "w": 923, "id": "a2-2-5-4-b6", "imp": "normal", "src": "/kb-assets/theory/p52_r2_58d92fdf3a8dcb62.png", "title": ""}, {"t": "list", "id": "a2-2-5-4-b7", "imp": "core", "title": "", "ordered": false, "items": ["（5）错误推测法：人们可以靠经验和直觉推测程序中可能存在的各种错误，从而有针对性地编写检查这些错误的用例。", "使用方法：极限值设计、特殊取值设计、特殊组网考虑、端到端用例考虑等。", "4、==软件测试的方法：白盒测试与黑盒测试==：从是否关心软件内部结构和具体实现的角度划分，测试方法主要有白盒测试和黑盒测试。白盒测试方法主要有代码检查法、静态结构分析法、静态质量度量法、逻辑覆盖法、基本路径测试法、域测试、符号测试、路径覆盖和程序变异等；黑盒测试方法主要包括等价类划分法、边界值分析法、错误推测法、因果图法、判定表驱动法、正交试验设计法、功能图法、场景法等。 从是否执行程序的角度划分，测试方法又可分为==静态测试和动态测试==。静态测试包括代码检查、静态结构分析、代码质量度量等；动态测试由3部分组成：构造测试实例、执行程序和分析程序的输出结果。", "5、==白盒测试与黑盒测试的区别==：^^按是否查看程序内部区分^^：==白盒测试研究程序的源代码和结构==；黑盒测试只关注输入数据与输出数据。", "6、==软件测试的分类与常用方法==：系统测试包括==模块测试、系统测试和验收测试三个阶段==，测试方法主要有黑盒测试和白盒测试。按不同维度还可划分：自动测试与人工测试；黑盒测试、白盒测试与灰盒测试；静态测试与动态测试。", "7、==黑盒测试与白盒测试的方法==：软件测试按测试用例设计方法的不同，分为==黑盒测试和白盒测试==，二者都属于动态测试。 软件调试的目的是定位问题并修改程序；软件测试的目的是发现至今尚未发现的错误。 黑盒测试的方法：等价类划分法、边界值分析法、错误推测法、因果图分析法。 白盒测试的方法：逻辑覆盖、基本路径测试。", "8、==静态测试与动态测试==：^^按是否运行程序区分（也可用于调试）^^：==静态测试是静态地检查程序代码、界面和文档==；动态测试是运行程序，检查输入数据与预期结果是否一致。"]}, {"t": "callout", "id": "a2-2-5-4-b8", "imp": "core", "kind": "tip", "text": "• ==静态测试（人工代码审查、走查，不运行程序）== vs ==动态测试（设计测试用例实际运行程序）==； • ==黑盒测试（功能测试，不关心内部代码逻辑，只检验输入与预期输出）==； • ==白盒测试（结构测试，根据内部代码分支条件设计测试用例，追求逻辑覆盖率）==； • 测试阶段自底向上：==单元测试（模块内部）→ 集成测试（接口联合）→ 系统测试（全系统软硬件）→ 验收测试（用户确认）==。", "title": "考向复习提示：软件测试两大方法与测试阶段体系"}, {"t": "callout", "id": "a2-2-5-4-b9", "imp": "core", "kind": "trap", "text": "软件工程经典定义（Myers 准则）：==“软件测试的唯一目的就是为了发现程序中尚未暴露的错误，而不是为了证明程序完全正确或没有错误！”==成功的测试是发现了新错误的测试；任何测试都绝不可能穷举所有输入证明软件 100% 毫无瑕疵！", "title": "高频易错陷阱：软件测试的目的不是证明程序没有错误！"}]$b90$::jsonb;
  v_search text := $s90$A2-2.5.4 软件测试的方法，白盒测试与黑盒测试。 1、软件测试 （1）软件测试：为了发现错误而执行程序的过程，成功的测试是发现了至今尚未发现的错误的测试。 （2）测试的目的就是希望能以最少的人力和时间发现潜在的各种错误和缺陷。 （3）一般软件测试分为：单元测试、集成测试、系统测试和验收测试。 ①、单元测试∶针对每个单元的测试，以确保每个模块能正常工作为目标。 ②、集成测试∶对已测试过的模块进行组装，进行集成测试，目的在于检验与软件设计相关的程序结构。 ③、系统测试∶检验软件产品能否与系统的其他部分（如硬件、数据库及操作人员）协调工作。 ④、验收（用户）测试∶检验软件产品质量的最后一道工序，主要突出用户的作用，同时软件开发人员也应有一定程度的参与。 （4）测试方法分类： ①、从是否需要执行被测软件的角度分为静态测试和动态测试： 静态测试包括代码检查、静态结构分析、代码质量度量，不实际运行软件，主要通过人工进行。 动态测试是通过运行软件来检验软件中的动态行为和运行结果的正确性。 ②、按功能分为白盒测试和黑盒测试。 2、白盒测试 （1）白盒测试也称为结构测试或逻辑测试，是把程序看成装在一只透明的白盒子里，测试者完全了解程序的结构和处理过程。它根据程序的内部逻辑来设计测试用例，检查程序中的逻辑通路是否都按预定的要求正确地工作。 （2）基本原则： 保证所测模块中每一独立路径至少执行一次。 保证所测模块所有判断的每一分支至少执行一次。 保证所测模块每一循环都在边界条件和一般条件下至少各执行一次。 验证所有内部数据结构的有效性。 按照白盒测试的基本原则，“白盒”法是穷举路径测试。 （3）白盒测试的方法：逻辑覆盖，基本路径测试。 （4）逻辑覆盖：语句覆盖、判定覆盖、条件覆盖、判定/条件覆盖、条件组合覆盖和路径覆盖发现错误的能力呈由弱至强的变化。 语句覆盖：每条语句至少执行一次。 判定覆盖：每个判定的每个分支至少执行一次。 条件覆盖：每个判定的每个条件应取到各种可能的值。 判定/条件覆盖：同时满足判定覆盖与条件覆盖。 条件组合覆盖：每个判定中各条件的每一种组合至少出现一次。 路径覆盖：使程序中每一条可能的路径至少执行一次。 （5）基本路径测试：白盒测试的一种常用方法是基本路径法，根据源代码构造程序流程图，转换为控制流程图，得到基本路径，进而为每条基本路径设计测试用例。基本路径法的一个关键步骤是识别出所有的基本路径。 3、黑盒测试 （1）黑盒测试也称功能测试或数据驱动测试，是把程序看成一只黑盒子，测试者完全不了解，或不考虑程序的结构和处理过程。它根据规格说明书的功能来设计测试用例，检查程序的功能是否符合规格说明的要求。 （2）黑盒测试的方法：等价划分法，边界值分析法，错误推测法。 （3）等价划分法：这是一种典型的黑盒测试方法，它是将程序的所有可能的输入数据划分成若干部分(及若干等价类)，然后从每个等价类中选取数据作为测试用例。 划分等价类：有效等价类、无效等价类 （4）边界值分析法：它是对各种输入、输出范围的边界情况设计测试用例的方法。 边界检验类型：数字、字符、位置、重量、大小、速度、方位、尺寸、空间等。 例如：手机号的位数是 11 位。 （5）错误推测法：人们可以靠经验和直觉推测程序中可能存在的各种错误，从而有针对性地编写检查这些错误的用例。 使用方法：极限值设计、特殊取值设计、特殊组网考虑、端到端用例考虑等。 4、软件测试的方法：白盒测试与黑盒测试：从是否关心软件内部结构和具体实现的角度划分，测试方法主要有白盒测试和黑盒测试。白盒测试方法主要有代码检查法、静态结构分析法、静态质量度量法、逻辑覆盖法、基本路径测试法、域测试、符号测试、路径覆盖和程序变异等；黑盒测试方法主要包括等价类划分法、边界值分析法、错误推测法、因果图法、判定表驱动法、正交试验设计法、功能图法、场景法等。 从是否执行程序的角度划分，测试方法又可分为静态测试和动态测试。静态测试包括代码检查、静态结构分析、代码质量度量等；动态测试由3部分组成：构造测试实例、执行程序和分析程序的输出结果。 5、白盒测试与黑盒测试的区别：按是否查看程序内部区分：白盒测试研究程序的源代码和结构；黑盒测试只关注输入数据与输出数据。 6、软件测试的分类与常用方法：系统测试包括模块测试、系统测试和验收测试三个阶段，测试方法主要有黑盒测试和白盒测试。按不同维度还可划分：自动测试与人工测试；黑盒测试、白盒测试与灰盒测试；静态测试与动态测试。 7、黑盒测试与白盒测试的方法：软件测试按测试用例设计方法的不同，分为黑盒测试和白盒测试，二者都属于动态测试。 软件调试的目的是定位问题并修改程序；软件测试的目的是发现至今尚未发现的错误。 黑盒测试的方法：等价类划分法、边界值分析法、错误推测法、因果图分析法。 白盒测试的方法：逻辑覆盖、基本路径测试。 8、静态测试与动态测试：按是否运行程序区分（也可用于调试）：静态测试是静态地检查程序代码、界面和文档；动态测试是运行程序，检查输入数据与预期结果是否一致。 考向复习提示：软件测试两大方法与测试阶段体系 • 静态测试（人工代码审查、走查，不运行程序） vs 动态测试（设计测试用例实际运行程序）； • 黑盒测试（功能测试，不关心内部代码逻辑，只检验输入与预期输出）； • 白盒测试（结构测试，根据内部代码分支条件设计测试用例，追求逻辑覆盖率）； • 测试阶段自底向上：单元测试（模块内部）→ 集成测试（接口联合）→ 系统测试（全系统软硬件）→ 验收测试（用户确认）。 高频易错陷阱：软件测试的目的不是证明程序没有错误！ 软件工程经典定义（Myers 准则）：“软件测试的唯一目的就是为了发现程序中尚未暴露的错误，而不是为了证明程序完全正确或没有错误！”成功的测试是发现了新错误的测试；任何测试都绝不可能穷举所有输入证明软件 100% 毫无瑕疵！$s90$;
  v_sr jsonb := $r90${"pdf": "理论复习.pdf", "pages": [51, 52], "spans": 42, "extra": ["考纲三级节点: A2-2.5.4 软件测试的方法，白盒测试与黑盒测试。", "题库补充：软件测试的方法：白盒测试与黑盒测试 (43题)", "题库补充：白盒测试与黑盒测试的区别 (35题)", "题库补充：软件测试的分类与常用方法 (22题)", "题库补充：黑盒测试与白盒测试的方法 (21题)", "题库补充：静态测试与动态测试 (15题)"]}$r90$::jsonb;
begin
  select r.rev_no, r.html
    into old_rev
    from kb_entry e
    join kb_revision r on r.node_id = e.node_id and r.rev_no = e.published_rev
   where e.node_id = 90;

  if not found then
    raise exception 'node 90 找不到已发布 revision';
  end if;
  if old_rev.rev_no <> 2 then
    raise exception 'node 90 expected rev 2, got %', old_rev.rev_no;
  end if;

  select coalesce(max(rev_no), 0) + 1 into v_rev
    from kb_revision
   where node_id = 90;

  insert into kb_revision (node_id, rev_no, blocks, html, search_text, source_ref)
  values (90, v_rev, v_blocks, old_rev.html, v_search, v_sr);

  update kb_entry
     set published_rev = v_rev,
         updated_at = now()
   where node_id = 90;
end $$;

do $$
declare
  old_rev record;
  v_rev integer;
  v_blocks jsonb := $b91$[{"t": "list", "id": "a2-2-5-5-b1", "imp": "core", "title": "", "ordered": false, "items": ["1、程序调试", "（1）==在对程序进行了成功的测试之后将进入程序调试（Debug，即排错）。程序的调试任务是诊断和改正程序中的错误。==", "（2）==程序调试的基本步骤：错误定位；修改设计和代码，以排除错误；进行回归测试，防止引进新的错误。==", "（3）软件调试可分为静态调试和动态调试。", "（4）主要的调试方法有：==强行排错法；回溯法；原因排除法，包括演绎法，归纳法和二分法。==", "2、==软件测试与程序调试的区别：==", "==软件测试是尽可能多地发现软件中的错误，而程序调试先要发现软件的错误，然后借助于一定的调试工具去执行找出软件错误的具体位置。==", "==软件测试贯穿整个软件生命期，调试主要在开发阶段。==", "3、==软件的可靠性包括正确性和健壮性。软件的健壮性是非常重要的软件外部量度标准。软件设计的健壮与否直接反映了分析设计和编码人员的水平。=="]}, {"t": "callout", "id": "a2-2-5-5-b2", "imp": "core", "kind": "tip", "text": "• ==软件测试（Testing）==：目标是==发现程序中是否存在错误（只负责报病）==，通常由专职软件测试工程师依据测试规程执行； • ==程序调试（Debugging）==：目标是==诊断并定位导致错误的根本原因并动手修改纠正代码（负责治病）==，通常由编写代码的软件开发人员本人负责完成。", "title": "考向复习提示：程序调试（Debug）与测试的本质区别"}, {"t": "callout", "id": "a2-2-5-5-b3", "imp": "core", "kind": "trap", "text": "• ==静态调试==：通过人工目测通读代码或代码走查或静态分析工具检查代码中的语法规范、未初始化变量与内存泄漏隐患； • ==动态调试==：在 IDE 中通过==设置断点（Breakpoint）、单步跳过（Step Over）、单步进入（Step Into）以及实时监视变量窗口==观察程序运行时内存状态；切勿颠倒静态与动态的手段区别！", "title": "高频易错陷阱：静态调试与动态调试的执行手段"}]$b91$::jsonb;
  v_search text := $s91$A2-2.5.5 程序的调试，静态调试与动态调试。 1、程序调试 （1）在对程序进行了成功的测试之后将进入程序调试（Debug，即排错）。程序的调试任务是诊断和改正程序中的错误。 （2）程序调试的基本步骤：错误定位；修改设计和代码，以排除错误；进行回归测试，防止引进新的错误。 （3）软件调试可分为静态调试和动态调试。 （4）主要的调试方法有：强行排错法；回溯法；原因排除法，包括演绎法，归纳法和二分法。 2、软件测试与程序调试的区别： 软件测试是尽可能多地发现软件中的错误，而程序调试先要发现软件的错误，然后借助于一定的调试工具去执行找出软件错误的具体位置。 软件测试贯穿整个软件生命期，调试主要在开发阶段。 3、软件的可靠性包括正确性和健壮性。软件的健壮性是非常重要的软件外部量度标准。软件设计的健壮与否直接反映了分析设计和编码人员的水平。 考向复习提示：程序调试（Debug）与测试的本质区别 • 软件测试（Testing）：目标是发现程序中是否存在错误（只负责报病），通常由专职软件测试工程师依据测试规程执行； • 程序调试（Debugging）：目标是诊断并定位导致错误的根本原因并动手修改纠正代码（负责治病），通常由编写代码的软件开发人员本人负责完成。 高频易错陷阱：静态调试与动态调试的执行手段 • 静态调试：通过人工目测通读代码或代码走查或静态分析工具检查代码中的语法规范、未初始化变量与内存泄漏隐患； • 动态调试：在 IDE 中通过设置断点（Breakpoint）、单步跳过（Step Over）、单步进入（Step Into）以及实时监视变量窗口观察程序运行时内存状态；切勿颠倒静态与动态的手段区别！$s91$;
  v_sr jsonb := $r91${"pdf": "理论复习.pdf", "pages": [52, 53], "spans": 11, "extra": ["考纲三级节点: A2-2.5.5 程序的调试，静态调试与动态调试。"]}$r91$::jsonb;
begin
  select r.rev_no, r.html
    into old_rev
    from kb_entry e
    join kb_revision r on r.node_id = e.node_id and r.rev_no = e.published_rev
   where e.node_id = 91;

  if not found then
    raise exception 'node 91 找不到已发布 revision';
  end if;
  if old_rev.rev_no <> 3 then
    raise exception 'node 91 expected rev 3, got %', old_rev.rev_no;
  end if;

  select coalesce(max(rev_no), 0) + 1 into v_rev
    from kb_revision
   where node_id = 91;

  insert into kb_revision (node_id, rev_no, blocks, html, search_text, source_ref)
  values (91, v_rev, v_blocks, old_rev.html, v_search, v_sr);

  update kb_entry
     set published_rev = v_rev,
         updated_at = now()
   where node_id = 91;
end $$;

commit;
